// Generate time-aware greeting
const hour = new Date().getHours();
const name = $input.first().json.caller_name || '';
const bizId = $input.first().json.business_id || 'default';

let timeGreet = 'Good evening';
if (hour < 12) timeGreet = 'Good morning';
else if (hour < 17) timeGreet = 'Good afternoon';

let greeting;
if (name) {
  greeting = `${timeGreet}! Welcome back ${name}! This is Priya. How can I help you today?`;
} else {
  greeting = `${timeGreet}! Thank you for calling. My name is Priya. How may I assist you?`;
}

return [{ json: { ...$input.first().json, greeting_text: greeting } }];

// Build TwiML response for greeting + start recording
// TTS returns audio, not the session, so read the call context from the node before it
const s = $('Generate Greeting').first().json;
const sid = s.session_id;
// Same base the signature check rebuilds the URL from; '&' must be '&amp;' inside XML
const base = String($env.N8N_BASE_URL || 'https://YOUR_N8N_URL').trim().replace(/\/+$/, '');
const turnUrl = `${base}/webhook/voice/turn?sid=${encodeURIComponent(sid)}&amp;biz=${encodeURIComponent(s.business_id || 'default')}`;

const msg = (s.greeting_text || 'Welcome! How can I help?').replace(/[&<>"]/g, '');

const twiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say voice="Polly.Aditi" language="en-IN">${msg}</Say>
  <Record maxLength="15" timeout="3" playBeep="false" transcribe="false"
    action="${turnUrl}" />
  <Say voice="Polly.Aditi" language="en-IN">I am still here if you need anything.</Say>
  <Record maxLength="15" timeout="5" playBeep="false" transcribe="false"
    action="${turnUrl}" />
</Response>`;

return [{ json: { ...s, twiml_response: twiml } }];

// Silence handler — progressive responses
const s = $input.first().json;
const sid = s.session_id;
// Same base the signature check rebuilds the URL from; '&' must be '&amp;' inside XML
const base = String($env.N8N_BASE_URL || 'https://YOUR_N8N_URL').trim().replace(/\/+$/, '');
const turnUrl = `${base}/webhook/voice/turn?sid=${encodeURIComponent(sid)}&amp;biz=${encodeURIComponent(s.business_id || 'default')}`;

const msg = "I didn't quite catch that. Could you please go ahead? I'm listening.";

const twiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say voice="Polly.Aditi" language="en-IN">${msg}</Say>
  <Record maxLength="15" timeout="3" playBeep="false" transcribe="false"
    action="${turnUrl}" />
  <Say voice="Polly.Aditi" language="en-IN">Hello? I am still here.</Say>
  <Record maxLength="15" timeout="5" playBeep="false" transcribe="false"
    action="${turnUrl}" />
</Response>`;

return [{ json: { ...s, twiml_response: twiml } }];

// Parse Deepgram response
const input = $input.first().json;
// Deepgram's response has no call context; take it from the turn webhook data
const ctx = $('Extract Turn Data').first().json;
let transcript = '', lang = 'en', confidence = 0;
try {
  const ch = input.results.channels[0];
  transcript = ch.alternatives[0].transcript || '';
  confidence = ch.alternatives[0].confidence || 0;
  lang = ch.detected_language || 'en';
} catch(e) { transcript = ''; }

const norm = {'ta':'ta','ta-IN':'ta','te':'te','te-IN':'te','kn':'kn','kn-IN':'kn','ml':'ml','ml-IN':'ml','en':'en','en-IN':'en','en-US':'en'};
const names = {ta:'Tamil',te:'Telugu',kn:'Kannada',ml:'Malayalam',en:'English'};
const nl = norm[lang] || 'en';

return [{ json: {
  session_id: ctx.session_id || '',
  business_id: ctx.business_id || 'default',
  caller_number: ctx.caller_number || '',
  business_number: ctx.business_number || '',
  caller_transcript: transcript,
  detected_language: nl,
  language_name: names[nl] || 'English',
  stt_confidence: confidence,
  is_empty: transcript.trim() === ''
}}];

