// AI Brain timeout fallback
// Keep the call context even if the AI Brain call failed or returned partial data
const s = { ...$('Parse STT Result').first().json, ...$input.first().json };
const fallback = {
  reply_text: 'I am sorry, could you repeat that? I missed what you said.',
  intent: 'unknown',
  emotion: 'neutral',
  action: {},
  booking_data: {}
};

// Use AI response if available, else fallback
const resp = s.reply_text ? s : fallback;

return [{ json: { ...s, ...resp } }];

// ═══ HUMANIZATION ENGINE ═══
const s = $input.first().json;
const resp = s.reply_text || 'Could you repeat that?';
const emo = s.emotion || 'neutral';

const fills = {
  neutral: ['Sure!','Absolutely.','Of course.','Right.','Got it.'],
  thinking: ['Let me check...','One moment...','Hmm, let me see...'],
  empathy: ['I understand.','I hear you.','That makes sense.']
};

let h = resp;
if (Math.random() < 0.55) {
  let set;
  if (emo === 'angry' || emo === 'frustrated') set = fills.empathy;
  else if (resp.length > 100) set = fills.thinking;
  else set = fills.neutral;
  h = set[Math.floor(Math.random() * set.length)] + ' ' + h;
}

return [{ json: { ...s, humanized_response: h } }];

// Build TwiML: speak response + record next turn
// TTS returns audio, not the session, so read the call context from the node before it
const s = $('Humanization Engine').first().json;
const sid = s.session_id;
// Same base the signature check rebuilds the URL from; '&' must be '&amp;' inside XML
const base = String($env.N8N_BASE_URL || 'https://YOUR_N8N_URL').trim().replace(/\/+$/, '');
const turnUrl = `${base}/webhook/voice/turn?sid=${encodeURIComponent(sid)}&amp;biz=${encodeURIComponent(s.business_id || 'default')}`;

const spoken = (s.humanized_response || s.reply_text || 'Could you repeat that?').replace(/[&<>"]/g, '');
const endCall = s.action && s.action.type === 'end_call';

let twiml;
if (endCall) {
  twiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say voice="Polly.Aditi" language="en-IN">${spoken}</Say>
  <Hangup/>
</Response>`;
} else if (s.action && s.action.type === 'transfer') {
  const escNum = (() => {
    // Never fall back to a placeholder: an unset number would transfer the caller to a stranger.
    const raw = String(s.action.number || s.escalation_number || $env.ESCALATION_PHONE || '').replace(/[\s()-]/g, '');
    return /^\+[1-9]\d{7,14}$/.test(raw) && raw !== '+919876543210' ? raw : null;
  })();
  if (!escNum) s.callback_required = true;
  twiml = escNum ? `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say voice="Polly.Aditi" language="en-IN">${spoken}</Say>
  <Dial timeout="30"><Number>${escNum}</Number></Dial>
  <Say voice="Polly.Aditi" language="en-IN">Sorry, our team is unavailable. We will call you back shortly.</Say>
</Response>`
  : `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say voice="Polly.Aditi" language="en-IN">Sorry, our team is unavailable right now. We will call you back shortly.</Say>
  <Hangup/>
</Response>`;
} else {
  twiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say voice="Polly.Aditi" language="en-IN">${spoken}</Say>
  <Record maxLength="15" timeout="3" playBeep="false" transcribe="false"
    action="${turnUrl}" />
  <Say voice="Polly.Aditi" language="en-IN">I am still here if you need anything.</Say>
  <Record maxLength="15" timeout="5" playBeep="false" transcribe="false"
    action="${turnUrl}" />
</Response>`;
}

return [{ json: { ...s, twiml_response: twiml } }];

