// Reject requests that did not come from Twilio before any call logic runs.
// Twilio signs: full request URL + every POST param sorted by name (name + value),
// HMAC-SHA1 with the account auth token, base64. The URL is rebuilt from N8N_BASE_URL,
// the same base the TwiML action URLs use, so it matches what Twilio requested.
// TWILIO_SIGNATURE_MODE: enforce (default) = reject | log = let through, flagged | off = skip.
// Needs the 'crypto' built-in: N8N_RUNNERS_ALLOWED_BUILT_IN_MODULES=crypto (legacy: NODE_FUNCTION_ALLOW_BUILTIN).
const WEBHOOK_PATH = '/webhook/voice/incoming';
const req = $input.first().json;
const mode = String($env.TWILIO_SIGNATURE_MODE || 'enforce').trim().toLowerCase();
const token = String($env.TWILIO_AUTH_TOKEN || '');
const base = String($env.N8N_BASE_URL || '').trim().replace(/\/+$/, '');
const query = req.query || {};
const qs = Object.keys(query)
  .map(k => `${encodeURIComponent(k)}=${encodeURIComponent(query[k])}`)
  .join('&');
const url = base + WEBHOOK_PATH + (qs ? `?${qs}` : '');
const provided = String((req.headers || {})['x-twilio-signature'] || '');

let crypto = null;
try { crypto = require('crypto'); } catch (e) { crypto = null; }

let valid = false;
let reason = 'ok';
if (mode === 'off') reason = 'check_disabled';
else if (!token) reason = 'auth_token_not_configured';
else if (!base) reason = 'base_url_not_configured';
else if (!provided) reason = 'missing_signature_header';
else if (!crypto) reason = 'crypto_module_not_allowed';
else {
  const body = req.body || {};
  const payload = url + Object.keys(body).sort()
    .map(k => [].concat(body[k] ?? '').slice().sort().map(v => k + v).join(''))
    .join('');
  const expected = Buffer.from(crypto.createHmac('sha1', token).update(payload, 'utf8').digest('base64'));
  const got = Buffer.from(provided);
  valid = expected.length === got.length && crypto.timingSafeEqual(expected, got);
  if (!valid) reason = 'signature_mismatch';
}

return [{ json: {
  ...req,
  signature_valid: valid,
  signature_reason: reason,
  signature_url: url,
  request_allowed: valid || mode === 'off' || mode === 'log'
} }];

// Reject requests that did not come from Twilio before any call logic runs.
// Twilio signs: full request URL + every POST param sorted by name (name + value),
// HMAC-SHA1 with the account auth token, base64. The URL is rebuilt from N8N_BASE_URL,
// the same base the TwiML action URLs use, so it matches what Twilio requested.
// TWILIO_SIGNATURE_MODE: enforce (default) = reject | log = let through, flagged | off = skip.
// Needs the 'crypto' built-in: N8N_RUNNERS_ALLOWED_BUILT_IN_MODULES=crypto (legacy: NODE_FUNCTION_ALLOW_BUILTIN).
const WEBHOOK_PATH = '/webhook/voice/turn';
const req = $input.first().json;
const mode = String($env.TWILIO_SIGNATURE_MODE || 'enforce').trim().toLowerCase();
const token = String($env.TWILIO_AUTH_TOKEN || '');
const base = String($env.N8N_BASE_URL || '').trim().replace(/\/+$/, '');
const query = req.query || {};
const qs = Object.keys(query)
  .map(k => `${encodeURIComponent(k)}=${encodeURIComponent(query[k])}`)
  .join('&');
const url = base + WEBHOOK_PATH + (qs ? `?${qs}` : '');
const provided = String((req.headers || {})['x-twilio-signature'] || '');

let crypto = null;
try { crypto = require('crypto'); } catch (e) { crypto = null; }

let valid = false;
let reason = 'ok';
if (mode === 'off') reason = 'check_disabled';
else if (!token) reason = 'auth_token_not_configured';
else if (!base) reason = 'base_url_not_configured';
else if (!provided) reason = 'missing_signature_header';
else if (!crypto) reason = 'crypto_module_not_allowed';
else {
  const body = req.body || {};
  const payload = url + Object.keys(body).sort()
    .map(k => [].concat(body[k] ?? '').slice().sort().map(v => k + v).join(''))
    .join('');
  const expected = Buffer.from(crypto.createHmac('sha1', token).update(payload, 'utf8').digest('base64'));
  const got = Buffer.from(provided);
  valid = expected.length === got.length && crypto.timingSafeEqual(expected, got);
  if (!valid) reason = 'signature_mismatch';
}

return [{ json: {
  ...req,
  signature_valid: valid,
  signature_reason: reason,
  signature_url: url,
  request_allowed: valid || mode === 'off' || mode === 'log'
} }];

// Decide whether this caller is with a human right now (open row in the Handoffs sheet).
// Paused + valid escalation number -> skip the AI and dial staff. Paused but no valid
// number -> the AI answers as usual (a dead line is worse). A Sheets error counts as not paused.
const s = $('Init Session Variables').first().json;
const digits = String(s.caller_number || '').replace(/\D/g, '');
const key = `${s.business_id || 'default'}:${digits}`;
const now = Date.now();

const row = $input.all().map(i => i.json)
  .find(r => String(r.handoff_key || '') === key && String(r.status || '').trim().toLowerCase() === 'active');
let paused = false;
if (row && digits) {
  const until = Date.parse(String(row.paused_until || ''));
  // Blank or unreadable paused_until keeps the pause on until staff set status to 'released'.
  paused = Number.isNaN(until) ? true : until > now;
}

const raw = String($env.ESCALATION_PHONE || '').replace(/[\s()-]/g, '');
const escNum = /^\+[1-9]\d{7,14}$/.test(raw) && raw !== '+919876543210' ? raw : '';

return [{ json: {
  ...s,
  handoff_key: key,
  bot_paused: paused,
  handoff_reason: paused ? String(row.reason || '') : '',
  escalation_number: escNum,
  route_to_human: paused && escNum !== ''
} }];

// Guest is already being handled by staff: connect them straight to a human.
const s = $input.first().json;
const twiml = `<?xml version="1.0" encoding="UTF-8"?>
<Response>
  <Say voice="Polly.Aditi" language="en-IN">Thank you for calling back. Connecting you to our team now.</Say>
  <Dial timeout="30"><Number>${s.escalation_number}</Number></Dial>
  <Say voice="Polly.Aditi" language="en-IN">Sorry, our team is unavailable right now. We will call you back shortly.</Say>
</Response>`;

return [{ json: { ...s, twiml_response: twiml } }];

